<?php
require_once __DIR__ . '/../config/db.php';require_once __DIR__ . '/../includes/functions.php';require_role(['admin']);$statuses=['Pending','Processing','Shipped','Completed','Cancelled'];
if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$status=$_POST['status']??'';if(in_array($status,$statuses,true)){$st=$pdo->prepare('UPDATE orders SET status=? WHERE id=?');$st->execute([$status,$id]);}header('Location: orders.php');exit;}
$orders=$pdo->query('SELECT o.*,u.email FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.created_at DESC')->fetchAll();$pageTitle='Manage Orders';include __DIR__.'/../includes/header.php';
?>
<div class="admin-shell"><h1>ORDER MANAGEMENT</h1><nav class="admin-nav"><a href="index.php">Dashboard</a><a href="products.php">Products</a><a href="categories.php">Categories</a></nav><div class="table-wrap"><table class="data-table"><thead><tr><th>Order</th><th>Customer</th><th>Date</th><th>Total</th><th>Status</th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td>#<?= (int)$o['id'] ?></td><td><?= e($o['full_name']) ?><br><small><?= e($o['email']) ?></small></td><td><?= e($o['created_at']) ?></td><td><?= money($o['total']) ?></td><td><form method="post" class="inline-form"><input type="hidden" name="id" value="<?= (int)$o['id'] ?>"><select name="status"><?php foreach($statuses as $s): ?><option <?= $o['status']===$s?'selected':'' ?>><?= e($s) ?></option><?php endforeach; ?></select><button class="btn" style="padding:8px">Update</button></form></td></tr><?php endforeach; ?></tbody></table></div></div>
<?php include __DIR__.'/../includes/footer.php'; ?>
